const item = $input.first().json;

let raw = '';
if (item.content?.[0]?.text) {
  raw = item.content[0].text;
} else if (Array.isArray(item) && item[0]?.content?.[0]?.text) {
  raw = item[0].content[0].text;
} else if (item.output?.[0]?.content?.[0]?.text) {
  raw = item.output[0].content[0].text;
} else if (typeof item.output === 'string') {
  raw = item.output;
} else if (typeof item.text === 'string') {
  raw = item.text;
} else {
  raw = JSON.stringify(item);
}

raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
const match = raw.match(/\{[\s\S]*\}/);
if (match) raw = match[0];

try {
  let parsed = JSON.parse(raw);
  if (parsed.content?.[0]?.text) {
    let inner = parsed.content[0].text.replace(/```json/gi, '').replace(/```/g, '').trim();
    const innerMatch = inner.match(/\{[\s\S]*\}/);
    if (innerMatch) inner = innerMatch[0];
    parsed = JSON.parse(inner);
  }

  return [{
    json: {
      Date_Time: parsed.Date_Time || parsed.date_time || new Date().toISOString().replace('T', ' ').substring(0, 19),
      Ticker: parsed.Ticker || parsed.ticker || 'NBIS',
      Verdict: parsed.Verdict || parsed.verdict || 'WATCH',
      Confidence: parsed.Confidence || parsed.confidence || '0%',
      Current_Price: parsed.Current_Price || parsed.current_price || '0',
      RVOL: parsed.RVOL || parsed.rvol || '1.0x',
      Market_Trend: parsed.Market_Trend || parsed.market_trend || 'Neutral',
      Entry_Trigger: parsed.Entry_Trigger || parsed.entry_trigger || '',
      Stop_Loss: parsed.Stop_Loss || parsed.stop_loss || '0',
      Target_Price: parsed.Target_Price || parsed.target_price || '0',
      Risk_Reward: parsed.Risk_Reward || parsed.risk_reward || '',
      Catalyst_Headline: parsed.Catalyst_Headline || parsed.catalyst_headline || '',
      Telegram_Report: raw,
      Outcome: parsed.Outcome || parsed.outcome || 'Pending',
      Realized_PnL: ''
    }
  }];
} catch (e) {
  return [{
    json: {
      Date_Time: new Date().toISOString().replace('T', ' ').substring(0, 19),
      Ticker: 'NBIS',
      Verdict: 'PARSE_ERROR',
      Confidence: '0%',
      Current_Price: '0',
      RVOL: '0x',
      Market_Trend: 'Error',
      Entry_Trigger: '',
      Stop_Loss: '0',
      Target_Price: '0',
      Risk_Reward: '',
      Catalyst_Headline: '',
      Telegram_Report: raw,
      Outcome: 'ERROR',
      Realized_PnL: ''
    }
  }];
}

const items = $input.all();
const pendingTrades = [];

// Дата отпреди 2 дни (48 часа) във формат YYYY-MM-DD
const twoDaysAgo = new Date(Date.now() - (48 * 60 * 60 * 1000));
const cutoffDateStr = twoDaysAgo.toISOString().substring(0, 10);

items.forEach((item, index) => {
  const row = item.json;

  // Проверяваме Outcome напълно независимо от регистъра (Pending, pending, PENDING)
  const outcome = String(row.Outcome || "").trim().toLowerCase();

  if (outcome === "pending" || outcome === "") {
    // Взимаме датата YYYY-MM-DD от Date_Time
    const dateStr = String(row.Date_Time || "").trim().substring(0, 10);

    // Сравняваме директно датата (ако е днес, вчера или завчера)
    const isRecent = !dateStr || dateStr >= cutoffDateStr;

    if (isRecent) {
      pendingTrades.push({
        json: {
          ...row,
          row_number: row.row_number || (index + 2)
        }
      });
    }
  }
});

return pendingTrades;

const trade = $('Loop Pending Trades').item.json;
const candleData = $input.first().json.values?.[0] || {};

const high = parseFloat(candleData.high || 0);
const low = parseFloat(candleData.low || 0);
const close = parseFloat(candleData.close || 0);

const target = parseFloat(String(trade.Target_Price).replace(/[^0-9.-]+/g, "")) || 0;
const stop = parseFloat(String(trade.Stop_Loss).replace(/[^0-9.-]+/g, "")) || 0;
const entry = parseFloat(String(trade.Current_Price).replace(/[^0-9.-]+/g, "")) || close;
const verdict = (trade.Verdict || "").toUpperCase().trim();
const rrStr = trade.Risk_Reward ? "+" + String(trade.Risk_Reward).replace("1:", "").trim() + "R" : "+2.0R";

let outcome = "OPEN / EXPIRED";
let pnl = "0.0R";
let exitPrice = close;

if (verdict === "BUY") {
  if (high >= target && target > 0) {
    outcome = "WIN (Hit TP)";
    pnl = rrStr;
    exitPrice = target;
  } else if (low <= stop && stop > 0) {
    outcome = "LOSS (Hit SL)";
    pnl = "-1.0R";
    exitPrice = stop;
  } else {
    const rMultiple = (close - entry) / (entry - stop || 1);
    pnl = (rMultiple >= 0 ? "+" : "") + rMultiple.toFixed(2) + "R (Unrealized)";
  }
} else if (verdict === "SELL" || verdict === "SHORT") {
  if (low <= target && target > 0) {
    outcome = "WIN (Hit TP)";
    pnl = rrStr;
    exitPrice = target;
  } else if (high >= stop && stop > 0) {
    outcome = "LOSS (Hit SL)";
    pnl = "-1.0R";
    exitPrice = stop;
  } else {
    const rMultiple = (entry - close) / (stop - entry || 1);
    pnl = (rMultiple >= 0 ? "+" : "") + rMultiple.toFixed(2) + "R (Unrealized)";
  }
} else if (verdict === "WATCH") {
  const isBullish = target > entry || target > stop;
  if (isBullish) {
    if (high >= target && target > 0) {
      outcome = "WATCH WIN (Hit Target)";
      pnl = rrStr;
      exitPrice = target;
    } else if (low <= stop && stop > 0) {
      outcome = "WATCH LOSS (Hit Stop)";
      pnl = "-1.0R";
      exitPrice = stop;
    } else {
      outcome = "WATCH (Range-bound / No Breakout)";
      pnl = "0.0R";
      exitPrice = close;
    }
  } else {
    if (low <= target && target > 0) {
      outcome = "WATCH WIN (Hit Target)";
      pnl = rrStr;
      exitPrice = target;
    } else if (high >= stop && stop > 0) {
      outcome = "WATCH LOSS (Hit Stop)";
      pnl = "-1.0R";
      exitPrice = stop;
    } else {
      outcome = "WATCH (Range-bound / No Breakdown)";
      pnl = "0.0R";
      exitPrice = close;
    }
  }
}

return {
  json: {
    row_number: trade.row_number,
    Date_Time: trade.Date_Time,
    Ticker: trade.Ticker,
    Verdict: trade.Verdict,
    Outcome: outcome,
    Exit_Price: exitPrice.toFixed(2),
    Realized_PnL: pnl,
    Daily_High: high,
    Daily_Low: low,
    Daily_Close: close
  }
};

